import React, { useState, useEffect } from 'react';
import MessagesList from '../Pages/Messages/MessagesList';
import ChatWindow from '../Pages/Messages/ChatWindow';
import { MessageSquare, AlertCircle, Users, Plus, RefreshCw } from 'lucide-react';
import useMessages from '../../../hooks/useMessages';

const MessagesPage = ({ user }) => {
  const [showChat, setShowChat] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const [showAdminList, setShowAdminList] = useState(false);
  const [availableAdmins, setAvailableAdmins] = useState([]);
  const [adminLoading, setAdminLoading] = useState(false);

  const { 
    conversations, 
    currentConversation, 
    messages,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAvailableAdmins
  } = useMessages();

  const userData = user;
  const isAdmin = userData?.role === 'admin';

  // Initialisation des conversations
  useEffect(() => {
    if (userData) {
      fetchConversations().catch(err => console.error('Erreur fetchConversations:', err));
    }
  }, [userData, fetchConversations]);

  // Rafraîchissement automatique pour admin
  useEffect(() => {
    if (isAdmin) {
      const interval = setInterval(() => fetchConversations(), 30000);
      return () => clearInterval(interval);
    }
  }, [isAdmin, fetchConversations]);

  const handleSelectConversation = async (conversation) => {
    setIsAnimating(true);
    try {
      await fetchMessages(conversation.id);
      setShowChat(true);
    } catch (err) {
      console.error('Erreur fetchMessages:', err);
    } finally {
      setIsAnimating(false);
    }
  };

  const handleSendMessage = async (conversationId, content) => {
    try {
      return await sendMessage(conversationId, content);
    } catch (err) {
      console.error('Erreur sendMessage:', err);
      throw err;
    }
  };

  const handleCreateNewConversation = async (adminId) => {
    try {
      const conversation = await getOrCreateConversation(adminId);
      if (conversation) {
        await fetchMessages(conversation.id);
        setShowChat(true);
        setShowAdminList(false);
      }
    } catch (err) {
      console.error('Erreur création conversation:', err);
    }
  };

  const loadAvailableAdmins = async () => {
    try {
      setAdminLoading(true);
      const admins = await fetchAvailableAdmins();
      setAvailableAdmins(admins);
    } catch (err) {
      console.error('Erreur fetchAvailableAdmins:', err);
    } finally {
      setAdminLoading(false);
    }
  };

  if (!userData) {
    return (
      <div className="min-h-[80vh] flex items-center justify-center">
        <div className="text-center max-w-md p-8">
          <AlertCircle className="h-16 w-16 text-red-500 mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-neutral-900 dark:text-white mb-3">Accès non autorisé</h1>
          <p className="text-neutral-600 dark:text-neutral-400 mb-6">
            Vous devez vous connecter pour accéder aux messages.
          </p>
          <button
            onClick={() => window.location.href = '/login'}
            className="px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-lg hover:opacity-90 transition-opacity"
          >
            Se connecter
          </button>
        </div>
      </div>
    );
  }

  return (
    <>
      {/* Header */}
      <div className="mb-6 md:mb-8 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-neutral-900 dark:text-white bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
            Messages {isAdmin ? '(Admin)' : ''}
          </h1>
          <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400 mt-1">
            {isAdmin ? 'Gérez les conversations des utilisateurs' : 'Discutez avec notre équipe de support'}
          </p>
        </div>
        <div className="flex items-center space-x-3">
          {!isAdmin && (
            <button
              onClick={() => { loadAvailableAdmins(); setShowAdminList(true); }}
              className="px-4 py-2 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-lg hover:opacity-90 transition-opacity flex items-center gap-2 whitespace-nowrap"
              disabled={adminLoading}
            >
              {adminLoading ? (
                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
              ) : <Plus className="w-4 h-4" />}
              {!adminLoading && 'Nouvelle conversation'}
            </button>
          )}
          <span className="px-3 py-1 text-xs font-medium bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 rounded-full">
            {conversations?.length || 0} conversation{conversations?.length !== 1 ? 's' : ''}
          </span>
        </div>
      </div>

      {/* Modal admins */}
      {showAdminList && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-neutral-900 rounded-2xl max-w-md w-full p-6">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Sélectionnez un conseiller</h3>
              <button onClick={() => setShowAdminList(false)} className="p-1 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg">✕</button>
            </div>
            {adminLoading ? (
              <div className="py-8 text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500 mx-auto mb-3"></div>
                <p className="text-neutral-500">Chargement des conseillers...</p>
              </div>
            ) : availableAdmins.length === 0 ? (
              <div className="py-8 text-center">
                <Users className="h-12 w-12 text-neutral-400 mx-auto mb-3" />
                <p className="text-neutral-600 dark:text-neutral-400">Aucun conseiller disponible pour le moment</p>
              </div>
            ) : (
              <div className="space-y-3">
                {availableAdmins.map(admin => (
                  <button
                    key={admin.id}
                    onClick={() => handleCreateNewConversation(admin.id)}
                    className="w-full p-4 text-left border border-neutral-200 dark:border-neutral-800 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors flex items-center gap-3"
                  >
                    <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold">
                      {admin.first_name?.charAt(0).toUpperCase() || 'A'}
                    </div>
                    <div className="flex-1">
                      <h4 className="font-medium text-neutral-900 dark:text-white">{admin.first_name} {admin.last_name}</h4>
                      <p className="text-sm text-neutral-500">Conseiller support</p>
                      {admin.conversation_count !== undefined && (
                        <p className="text-xs text-neutral-400">{admin.conversation_count} conversation{admin.conversation_count !== 1 ? 's' : ''} en cours</p>
                      )}
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Grid principale */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Liste des conversations */}
        <div className={`lg:col-span-1 ${showChat ? 'hidden md:block' : 'block'}`}>
          <MessagesList 
            conversations={conversations}
            currentConversation={currentConversation}
            loading={loading}
            onSelectConversation={handleSelectConversation}
            isAdmin={isAdmin}
            user={userData}
          />
        </div>

        {/* Fenêtre de chat */}
        <div className={`lg:col-span-2 ${showChat ? 'block' : 'hidden md:block'}`}>
          {currentConversation && (
            <ChatWindow 
              conversation={currentConversation}
              messages={messages}
              loading={loading}
              onSendMessage={handleSendMessage}
              onClose={() => setShowChat(false)}
              isAdmin={isAdmin}
              user={userData}
            />
          )}
        </div>
      </div>
    </>
  );
};

export default MessagesPage;
